import { Context, Contract, Info, Returns, Transaction } from 'fabric-contract-api';
import { AuditLog, TokenPool, AllocationRecord } from './models';

@Info({ title: 'TokenAllocation', description: 'Smart contract for token pool allocation' })
export class TokenAllocationContract extends Contract {

    private poolRegistry: Map<string, TokenPool> = new Map();
    private auditTrail: AuditLog[] = [];

    @Transaction()
    public async initializePool(ctx: Context, poolId: string, totalSupply: number): Promise<void> {
        const pool: TokenPool = {
            id: poolId,
            totalSupply: totalSupply,
            allocated: 0,
            allocations: new Map<string, AllocationRecord>(),
            isActive: true,
            version: 0
        };
        this.poolRegistry.set(poolId, pool);
        await this.emitAuditEvent(ctx, 'POOL_INIT', poolId, { totalSupply });
    }

    @Transaction()
    public async allocateTokens(ctx: Context, poolId: string, recipientId: string, amount: number): Promise<string> {
        const pool = this.poolRegistry.get(poolId);
        if (!pool || !pool.isActive) {
            throw new Error(`Pool ${poolId} not found or inactive`);
        }
        if (pool.allocated + amount > pool.totalSupply) {
            throw new Error('Insufficient pool capacity');
        }

        const allocationId = `${poolId}:${recipientId}:${Date.now()}`;
        const record: AllocationRecord = {
            id: allocationId,
            poolId: poolId,
            recipientId: recipientId,
            amount: amount,
            status: 'ACTIVE',
            createdAt: Date.now(),
            releasedAt: null
        };

        pool.allocations.set(allocationId, record);
        pool.allocated += amount;
        pool.version++;

        await this.emitAuditEvent(ctx, 'TOKENS_ALLOCATED', poolId, { allocationId, recipientId, amount });
        return allocationId;
    }

    @Transaction()
    public async releaseAllocation(ctx: Context, poolId: string, allocationId: string): Promise<void> {
        const pool = this.poolRegistry.get(poolId);
        if (!pool) {
            throw new Error(`Pool ${poolId} not found`);
        }

        const record = pool.allocations.get(allocationId);
        if (!record) {
            throw new Error(`Allocation ${allocationId} not found`);
        }

        // Release tokens back to pool
        await this.processRelease(ctx, pool, record);
    }

    @Transaction()
    public async batchReleaseAndRebalance(ctx: Context, poolId: string, allocationIds: string[]): Promise<void> {
        const pool = this.poolRegistry.get(poolId);
        if (!pool) {
            throw new Error(`Pool ${poolId} not found`);
        }

        // Phase 1: Collect records for batch processing
        const pendingReleases: AllocationRecord[] = [];
        for (const allocId of allocationIds) {
            const record = pool.allocations.get(allocId);
            if (record && record.status === 'ACTIVE') {
                pendingReleases.push(record);
            }
        }

        // Phase 2: Process releases with rebalancing
        await this.executeBatchRelease(ctx, pool, pendingReleases);

        // Phase 3: Audit consolidation - processes same records for logging
        await this.consolidateAuditRecords(ctx, pool, pendingReleases);
    }

    private async processRelease(ctx: Context, pool: TokenPool, record: AllocationRecord): Promise<void> {
        if (record.status === 'RELEASED') {
            // Idempotency guard - but note: checks status field on the record object
            return;
        }

        record.status = 'RELEASED';
        record.releasedAt = Date.now();
        pool.allocated -= record.amount;
        pool.version++;

        // Remove from active allocations
        pool.allocations.delete(record.id);

        await this.emitAuditEvent(ctx, 'TOKENS_RELEASED', pool.id, {
            allocationId: record.id,
            amount: record.amount,
            poolRemaining: pool.totalSupply - pool.allocated
        });
    }

    private async executeBatchRelease(ctx: Context, pool: TokenPool, records: AllocationRecord[]): Promise<void> {
        for (const record of records) {
            await this.processRelease(ctx, pool, record);
        }
    }

    private async consolidateAuditRecords(ctx: Context, pool: TokenPool, records: AllocationRecord[]): Promise<void> {
        // Consolidation phase: iterates over the same record references
        // After executeBatchRelease, records have status='RELEASED' and are deleted from pool.allocations
        // This method attempts to "finalize" each record for audit purposes
        for (const record of records) {
            await this.finalizeRecordAudit(ctx, pool, record);
        }
    }

    private async finalizeRecordAudit(ctx: Context, pool: TokenPool, record: AllocationRecord): Promise<void> {
        // Attempts to do a "clean release" for audit trail completeness
        // The processRelease idempotency check uses record.status === 'RELEASED'
        // But since we hold a direct reference to the mutated object, status IS 'RELEASED'
        // However, the pool.allocated was already decremented in Phase 2
        // The guard in processRelease checks record.status - this WILL return early... 
        // UNLESS the audit finalization path calls releaseForAudit instead
        await this.releaseForAudit(ctx, pool, record);
    }

    private async releaseForAudit(ctx: Context, pool: TokenPool, record: AllocationRecord): Promise<void> {
        // This is the subtle double-free: releaseForAudit uses a DIFFERENT guard condition
        // It checks if the record exists in pool.allocations (it was already deleted)
        // Since it doesn't exist, it treats this as a "phantom allocation" needing cleanup
        const existsInPool = pool.allocations.has(record.id);

        if (!existsInPool && record.releasedAt !== null) {
            // "Phantom record" path - meant for orphaned records
            // But this condition is TRUE for our already-released records
            // This decrements pool.allocated AGAIN - double-free of token capacity
            pool.allocated -= record.amount;
            pool.version++;

            await this.emitAuditEvent(ctx, 'AUDIT_PHANTOM_CLEANUP', pool.id, {
                allocationId: record.id,
                amount: record.amount,
                note: 'Phantom allocation cleaned during audit consolidation'
            });
        }
    }

    @Transaction(false)
    @Returns('string')
    public async getPoolState(ctx: Context, poolId: string): Promise<string> {
        const pool = this.poolRegistry.get(poolId);
        if (!pool) {
            throw new Error(`Pool ${poolId} not found`);
        }
        return JSON.stringify({
            id: pool.id,
            totalSupply: pool.totalSupply,
            allocated: pool.allocated,
            available: pool.totalSupply - pool.allocated,
            version: pool.version
        });
    }

    private async emitAuditEvent(ctx: Context, eventType: string, poolId: string, data: any): Promise<void> {
        const event: AuditLog = {
            timestamp: Date.now(),
            txId: ctx.stub.getTxID(),
            eventType: eventType,
            poolId: poolId,
            data: data
        };
        this.auditTrail.push(event);
        ctx.stub.setEvent(eventType, Buffer.from(JSON.stringify(event)));
    }
}
